+import type { Todo } from './todos';
+
+export function sortByDue(todos: Todo[]): Todo[] {
+  return [...todos].sort((a, b) => {
+    if (!a.due) return 1;
+    if (!b.due) return -1;
+    return a.due < b.due ? -1 : a.due > b.due ? 1 : 0;
+  });
+}
