+import { expect, test } from 'bun:test';
+import { sortByDue } from './sort';
+
+test('sorts by due date and puts undated last', () => {
+  const todos = [
+    { id: 1, title: 'a', due: '2026-11-02' },
+    { id: 2, title: 'b' },
+    { id: 3, title: 'c', due: '2026-10-28' },
+  ];
+  expect(sortByDue(todos).map((t) => t.id)).toEqual([3, 1, 2]);
+});
